<?php
declare(strict_types=1);
function commissionMemberMatches(array $u,array $m):bool{return $u['role']==='commission'&&($m['personId']??null)===$u['person']&&(!($m['memberId']??null)||$m['memberId']===$u['id']);}
function commissionSnapshotContains(array $u,array $members):bool{foreach($members as $m)if(commissionMemberMatches($u,$m))return true;return false;}
function saveCommission(array $u,string $method,array $b):array{
 fullManager($u);$t=$u['tenant'];$old=null;if($method==='PUT'){$old=record($t,'appointments',$b['id']??'');if(!$old)throw new Fault('Comissão não encontrada.',404);if($old['version']!==($b['version']??null))throw new Fault('Comissão alterada. Atualize antes de salvar.',409);if(!$old['active'])throw new Fault('Uma comissão encerrada não pode ser alterada.');}elseif($method!=='POST')throw new Fault('Método não permitido.',405);
 $unit=record($t,'units',$b['unit']??'');$plan=record($t,'plans',$b['plan']??'');if(!$unit||!$plan||$unit['power']!==$plan['power'])throw new Fault('Unidade e plano devem pertencer ao mesmo poder.');$members=[];
 foreach($b['members']??[] as $input){$link=record($t,'links',$input['linkId']??'');if(!$link||$link['probation']!=='Concluído'||!in_array($input['representation']??'',['Administração','Sindicato','Assembleia']))throw new Fault('Selecione servidor de carreira com estágio concluído e representação válida.');$account=one('SELECT * FROM tr_users WHERE tenant=? AND person=? AND role=? AND active=1',[$t,$link['personId'],'commission']);$members[]=['memberId'=>$account['id']??null,'linkId'=>$link['id'],'personId'=>$link['personId'],'name'=>$link['name'],'admission'=>$link['admission'],'representation'=>$input['representation'],'indication'=>need($input['indication']??'','origem da indicação',500)];}
 if(!$members||count($members)>100||count(array_unique(array_column($members,'personId')))!==count($members))throw new Fault('Informe de 1 a 100 integrantes distintos. Uma pessoa não pode ocupar duas vagas com matrículas diferentes.');$start=day($b['start']??'');$end=day($b['end']??'');if($end<$start)throw new Fault('Mandato inválido.');
 $a=['id'=>$old['id']??uid(),'name'=>need($b['name']??'','comissão',120),'plan'=>$plan['id'],'unit'=>$unit['id'],'lotation'=>trim((string)($b['lotation']??'')),'act'=>need($b['act']??'','ato e fundamento legal',1000),'start'=>$start,'end'=>$end,'members'=>$members,'active'=>true,'history'=>$old['history']??[]];if(strlen($a['lotation'])>240)throw new Fault('Lotação muito longa.');
 $pending=[];if($old){$prior=$old;unset($prior['history']);$a['history'][]=['previous'=>$prior,'reason'=>need($b['reason']??'','motivo da alteração',1000),'actor'=>$u['id'],'at'=>date(DATE_ATOM)];foreach(records($t,'certificates') as $c)if($c['appointment']===$old['id']&&certificateStatus($c)==='Em análise'){$p=record($t,'links',$c['link']);if(!$p||$a['plan']!==$p['planId']||$a['unit']!==$p['unitId']||$a['lotation']&&$a['lotation']!==$p['lotation'])throw new Fault('Existem documentos pendentes fora do novo escopo. Conclua ou encaminhe os processos antes de alterar a unidade, o plano ou a lotação.');foreach($members as $m)if($m['personId']===$p['personId']||$m['admission']>=$p['admission'])throw new Fault('Há integrante sem a antiguidade exigida para um servidor com documento pendente nesta comissão.');$pending[]=$c;}}
 $saved=save($t,'appointments',$a,$old['version']??null);if($old&&j($old['members'])!==j($members))foreach($pending as $c){$c['reviewHistory'][]=['reviewers'=>$c['reviewers'],'votes'=>$c['votes'],'appointmentVersion'=>$old['version'],'actor'=>$u['id'],'at'=>date(DATE_ATOM)];$c['reviewers']=$members;$ids=array_filter(array_column($members,'memberId'));$c['votes']=array_values(array_filter($c['votes'],fn($v)=>in_array($v['member'],$ids,true)));save($t,'certificates',$c,$c['version']);}audit($t,$old?'commission.update':'commission.create',$a['id']);return ['id'=>$saved['id'],'pendingUpdated'=>count($pending)];
}
